import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import { describe, expect, it } from 'vitest'

import { httpDateToIso, parseXmlDvc, renderXmlDvc, yamlStr } from '../src/dvc'
import { md5Hex } from '../src/snapshot'

type Golden = {
  name: string
  dvc: string
  content: string
  headers: { ETag?: string, 'Last-Modified'?: string } | null
  fetched: string
  expected: string
}

// Generated by `njsp/tests/test_refresh_data.py::test_snapshot_worker_goldens` (Python `render_xml_dvc`).
const goldens: Golden[] = JSON.parse(readFileSync(join(__dirname, 'fixtures', 'dvc-golden.json'), 'utf-8'))

describe('renderXmlDvc ≡ refresh_data.render_xml_dvc', () => {
  it('has the expected golden cases', () => {
    expect(goldens.map(g => g.name)).toEqual([
      'full',
      'full-weak-etag',
      'full-etag-only',
      'full-lm-only',
      'full-no-headers',
      'full-no-response',
      'bare',
      'bare-no-response',
      'bare-unquoted-etag',
      'bare-numeric-etag',
    ])
  })
  for (const g of goldens) {
    it(g.name, () => {
      const content = new TextEncoder().encode(g.content)
      const headers = g.headers === null
        ? null
        : { etag: g.headers.ETag ?? null, lastModified: g.headers['Last-Modified'] ?? null }
      const actual = renderXmlDvc(g.dvc, { md5: md5Hex(content), size: content.length }, headers, g.fetched)
      expect(actual).toBe(g.expected)
    })
  }
})

describe('parseXmlDvc', () => {
  it('reads deps/outs fields', () => {
    expect(parseXmlDvc(goldens[0].dvc)).toEqual({
      etag: '"2f375-65f239beeffed"',
      mtime: '2026-10-31T14:20:04+00:00',
      md5: 'aedd16377beb2b1a8a766809c8951415',
      size: 193397,
    })
  })
  it('reads a bare (older-year) .dvc', () => {
    expect(parseXmlDvc(goldens.find(g => g.name === 'bare')!.dvc)).toEqual({
      md5: '017b63c673518b66eff6dcabf5af4778',
      size: 198875,
    })
  })
  it('round-trips its own output', () => {
    const g = goldens.find(g => g.name === 'bare')!
    expect(parseXmlDvc(g.expected)).toEqual({
      etag: '"4bc21-65f239bead584"',
      mtime: '2026-11-01T15:20:05+00:00',
      md5: md5Hex(new TextEncoder().encode(g.content)),
      size: g.content.length,
    })
  })
})

describe('yamlStr', () => {
  it('quotes like PyYAML', () => {
    expect([
      '"abc-123"',
      'W/"abc"',
      'abc-123',
      '12345',
      '2026-10-31',
      '2026-10-31T14:20:04+00:00',
      'aedd16377beb2b1a8a766809c8951415',
      '1e5',
      'yes',
      "it's",
      '',
    ].map(yamlStr)).toEqual([
      `'"abc-123"'`,
      'W/"abc"',
      'abc-123',
      `'12345'`,
      `'2026-10-31'`,
      `'2026-10-31T14:20:04+00:00'`,
      'aedd16377beb2b1a8a766809c8951415',
      '1e5',
      `'yes'`,
      "it's",
      `''`,
    ])
  })
})

describe('httpDateToIso', () => {
  it('matches parsedate_to_datetime().isoformat()', () => {
    expect([
      'Sat, 31 Oct 2026 14:20:04 GMT',
      'Sun, 01 Nov 2026 05:07:09 GMT',
      'Sun, 01 Nov 2026 05:07:09 +0100',
    ].map(httpDateToIso)).toEqual([
      '2026-10-31T14:20:04+00:00',
      '2026-11-01T05:07:09+00:00',
      '2026-11-01T05:07:09+01:00',
    ])
  })
})
